func:
const p = msg.payload || {};
const action = p.action;

const queries = {
  students: "SELECT s.id, s.name, s.usn, c.name AS class, s.rfid_uid, IF(s.face_embedding IS NOT NULL AND JSON_LENGTH(s.face_embedding)>0,'Enrolled','Not enrolled') AS face_status, IF(s.active=1,'Active','Inactive') AS status, DATE_FORMAT(s.created_at,'%d-%m-%Y %H:%i') AS registered_at FROM students s JOIN classes c ON c.id=s.class_id ORDER BY s.name",
  teachers: "SELECT id,name,teacher_id,email,mobile,IF(active=1,'Active','Inactive') AS status,DATE_FORMAT(created_at,'%d-%m-%Y %H:%i') AS registered_at FROM teachers ORDER BY id DESC",
  timetable: "SELECT tt.id,tt.class_id,tt.subject_id,tt.teacher_id,tt.room_id,c.name AS class, tt.day_of_week AS day, tt.period_number AS period,TIME_FORMAT(tt.start_time,'%H:%i') AS start_time,TIME_FORMAT(tt.end_time,'%H:%i') AS end_time,s.name AS subject, t.name AS teacher, COALESCE(r.room_number,'—') AS room,IF(tt.active=1,'Enabled','Archived') AS status,(SELECT COUNT(*) FROM attendance_sessions hx WHERE hx.timetable_id=tt.id) AS history_count FROM timetable tt LEFT JOIN classes c ON c.id=tt.class_id LEFT JOIN subjects s ON s.id=tt.subject_id LEFT JOIN teachers t ON t.id=tt.teacher_id LEFT JOIN rooms r ON r.id=tt.room_id ORDER BY FIELD(tt.day_of_week,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'),tt.period_number",
  attendance: "SELECT a.id,DATE_FORMAT(ses.session_date,'%Y-%m-%d') AS date,tt.period_number AS period,c.name AS class,sub.name AS subject,t.name AS teacher,r.room_number AS room,st.name AS student,st.usn,a.automated_status,a.teacher_status,a.final_status,IF(a.teacher_override=1,'Yes','No') AS teacher_override,DATE_FORMAT(a.confirmed_at,'%d-%m-%Y %H:%i') AS confirmed_at,DATE_FORMAT(a.submitted_at,'%d-%m-%Y %H:%i') AS submitted_at FROM attendance a LEFT JOIN attendance_sessions ses ON ses.id=a.session_id LEFT JOIN timetable tt ON tt.id=ses.timetable_id LEFT JOIN classes c ON c.id=tt.class_id LEFT JOIN subjects sub ON sub.id=tt.subject_id LEFT JOIN teachers t ON t.id=tt.teacher_id LEFT JOIN rooms r ON r.id=tt.room_id LEFT JOIN students st ON st.id=a.student_id ORDER BY ses.session_date DESC,tt.period_number,a.id LIMIT 500",
  rooms: "SELECT r.id,r.room_number,r.camera_id,IF(r.active=1,'Enabled','Disabled') AS room_status,IF(EXISTS(SELECT 1 FROM attendance_sessions ses JOIN timetable tt ON tt.id=ses.timetable_id WHERE tt.room_id=r.id AND ses.session_date=CURDATE() AND ses.status='active' AND NOW() BETWEEN ses.start_time AND ses.end_time),'Active','Inactive') AS camera_status,DATE_FORMAT(r.created_at,'%d-%m-%Y %H:%i') AS created_at FROM rooms r ORDER BY r.room_number",
  classes: "SELECT id,name FROM classes ORDER BY name",
  subjects: "SELECT id,name,code FROM subjects ORDER BY name",
  attendance_sessions: "SELECT ses.id AS session_id,DATE_FORMAT(ses.session_date,'%Y-%m-%d') AS date,TIME_FORMAT(ses.start_time,'%H:%i') AS start_time,TIME_FORMAT(ses.end_time,'%H:%i') AS end_time,ses.status,tt.period_number AS period,c.name AS class,sub.name AS subject,t.name AS teacher,r.room_number AS room,COUNT(a.id) AS students,SUM(CASE WHEN COALESCE(a.final_status,a.teacher_status,a.automated_status)='present' THEN 1 ELSE 0 END) AS present,SUM(CASE WHEN COALESCE(a.final_status,a.teacher_status,a.automated_status)='absent' THEN 1 ELSE 0 END) AS absent,SUM(CASE WHEN COALESCE(a.final_status,a.teacher_status,a.automated_status)='review' THEN 1 ELSE 0 END) AS review FROM attendance_sessions ses JOIN timetable tt ON tt.id=ses.timetable_id LEFT JOIN classes c ON c.id=tt.class_id LEFT JOIN subjects sub ON sub.id=tt.subject_id LEFT JOIN teachers t ON t.id=tt.teacher_id LEFT JOIN rooms r ON r.id=tt.room_id LEFT JOIN attendance a ON a.session_id=ses.id GROUP BY ses.id,ses.session_date,ses.start_time,ses.end_time,ses.status,tt.period_number,c.name,sub.name,t.name,r.room_number ORDER BY ses.session_date DESC,ses.start_time DESC LIMIT 300"
};

function q(section, topic, values=[]) { return {_client:msg._client, section, topic, payload:values}; }
if (action === 'load_all' || action === 'load_home') return [[q('students',queries.students),q('teachers',queries.teachers),q('timetable',queries.timetable),q('attendance_sessions',queries.attendance_sessions),q('rooms',queries.rooms),q('classes',queries.classes),q('subjects',queries.subjects)]];
if(action==='load_attendance_details'){const id=Number(p.session_id);if(!Number.isInteger(id)||id<1){node.error('Invalid attendance session',msg);return null;}return q('attendance',"SELECT a.id,st.name AS student,st.usn,COALESCE((SELECT ci.checkin_method FROM student_checkins ci WHERE ci.session_id=a.session_id AND ci.student_id=a.student_id ORDER BY ci.checked_in_at DESC LIMIT 1),'—') AS checkin_method,COALESCE((SELECT CONCAT(UPPER(LEFT(wr.result,1)),LOWER(SUBSTRING(wr.result,2)),IF(wr.confidence IS NULL,'',CONCAT(' · ',FORMAT(wr.confidence,2)))) FROM wave_results wr WHERE wr.session_id=a.session_id AND wr.student_id=a.student_id AND wr.wave_number=1 LIMIT 1),'Pending') AS wave_1,COALESCE((SELECT CONCAT(UPPER(LEFT(wr.result,1)),LOWER(SUBSTRING(wr.result,2)),IF(wr.confidence IS NULL,'',CONCAT(' · ',FORMAT(wr.confidence,2)))) FROM wave_results wr WHERE wr.session_id=a.session_id AND wr.student_id=a.student_id AND wr.wave_number=2 LIMIT 1),'Pending') AS wave_2,COALESCE((SELECT CONCAT(UPPER(LEFT(wr.result,1)),LOWER(SUBSTRING(wr.result,2)),IF(wr.confidence IS NULL,'',CONCAT(' · ',FORMAT(wr.confidence,2)))) FROM wave_results wr WHERE wr.session_id=a.session_id AND wr.student_id=a.student_id AND wr.wave_number=3 LIMIT 1),'Pending') AS wave_3,a.automated_status,a.teacher_status,a.final_status,IF(a.teacher_override=1,'Yes','No') AS teacher_override,DATE_FORMAT(a.confirmed_at,'%d-%m-%Y %H:%i') AS confirmed_at,DATE_FORMAT(a.submitted_at,'%d-%m-%Y %H:%i') AS submitted_at FROM attendance a JOIN students st ON st.id=a.student_id WHERE a.session_id=? ORDER BY st.name",[id]);}
if (action && action.startsWith('load_')) { const section=action.slice(5); if(queries[section]) return q(section,queries[section]); return null; }

if (action === 'set_teacher_status') {
  const id=Number(p.id), active=Number(p.active);
  if(!Number.isInteger(id)||id<1||![0,1].includes(active)){node.error('Invalid teacher status request',msg);return null;}
  return q('_mutation_teachers', 'UPDATE teachers t LEFT JOIN continio_accounts a ON a.teacher_id=t.id SET t.active=?, a.active=? WHERE t.id=?', [active,active,id]);
}
if (action === 'update_student_embedding') {
  const id=Number(p.id), embedding=p.face_embedding;
  if(!Number.isInteger(id)||id<1){node.error('Invalid student ID',msg);return null;}
  if(!Array.isArray(embedding)||embedding.length!==128||embedding.some(v=>typeof v!=='number'||!Number.isFinite(v))){node.error('A valid 128-value face embedding is required',msg);return null;}
  return q('_mutation', 'UPDATE students SET face_embedding=?,photo_path=NULL WHERE id=?', [JSON.stringify(embedding),id]);
}
if (action === 'update_student_rfid') {
  const id=Number(p.id), uid=String(p.rfid_uid||'').replace(/[^0-9a-f]/gi,'').toUpperCase();
  if(!Number.isInteger(id)||id<1||!/^[0-9A-F]{8,20}$/.test(uid)){node.error('Invalid student or RFID UID',msg);return null;}
  return q('_mutation', 'UPDATE students SET rfid_uid=? WHERE id=?', [uid,id]);
}
if (action === 'set_student_status') {
  const id=Number(p.id), active=Number(p.active);
  if(!Number.isInteger(id)||id<1||![0,1].includes(active)){node.error('Invalid student status request',msg);return null;}
  return q('_mutation', 'UPDATE students SET active=? WHERE id=?', [active,id]);
}
if (action === 'add_student') {
  const classId=Number(p.class_id), embedding=p.face_embedding;
  if(!p.name||!p.usn||!Number.isInteger(classId)){node.error('Complete the student name, USN and class',msg);return null;}
  if(!Array.isArray(embedding)||embedding.length!==128||embedding.some(v=>typeof v!=='number'||!Number.isFinite(v))){node.error('A valid 128-value face embedding is required',msg);return null;}
  const uid=p.rfid_uid?String(p.rfid_uid).trim():null;
  return q('_mutation', 'INSERT INTO students (name,usn,class_id,rfid_uid,face_embedding,photo_path) VALUES (?,?,?,?,?,NULL)', [String(p.name).trim(),String(p.usn).trim().toUpperCase(),classId,uid,JSON.stringify(embedding)]);
}
if (action === 'add_room') {
  if(!p.room_number){node.error('Room number required',msg);return null;}
  return q('_mutation_rooms', 'INSERT INTO rooms (room_number,camera_id) VALUES (?,?)', [String(p.room_number).trim(),p.camera_id?String(p.camera_id).trim():null]);
}
if (['add_timetable','update_timetable'].includes(action)) {
  const vals=[p.class_id,p.day_of_week,p.period_number,p.start_time,p.end_time,p.subject_id,p.teacher_id,p.room_id];
  if(vals.some(v=>v===undefined||v==='')){node.error('Complete every timetable field',msg);return null;}
  const classId=Number(p.class_id),day=String(p.day_of_week),period=Number(p.period_number),start=String(p.start_time),end=String(p.end_time),subject=Number(p.subject_id),teacher=Number(p.teacher_id),room=Number(p.room_id);
  if(start>=end){node.error('End time must be after start time',msg);return null;}
  const values=[classId,day,period,start,end,subject,teacher,room];
  if(action==='update_timetable'){const id=Number(p.id);if(!Number.isInteger(id)||id<1){node.error('Invalid timetable ID',msg);return null;}const sql='UPDATE timetable target LEFT JOIN timetable conflict ON conflict.active=1 AND conflict.id<>target.id AND conflict.day_of_week=? AND conflict.start_time<? AND conflict.end_time>? AND (conflict.teacher_id=? OR conflict.room_id=? OR conflict.class_id=?) SET target.class_id=?,target.day_of_week=?,target.period_number=?,target.start_time=?,target.end_time=?,target.subject_id=?,target.teacher_id=?,target.room_id=? WHERE target.id=? AND conflict.id IS NULL';return q('_mutation_timetable',sql,[day,end,start,teacher,room,classId,...values,id]);}
  const sql='INSERT INTO timetable (class_id,day_of_week,period_number,start_time,end_time,subject_id,teacher_id,room_id,active) SELECT ?,?,?,?,?,?,?,?,1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM timetable conflict WHERE conflict.active=1 AND conflict.day_of_week=? AND conflict.start_time<? AND conflict.end_time>? AND (conflict.teacher_id=? OR conflict.room_id=? OR conflict.class_id=?))';return q('_mutation_timetable',sql,[...values,day,end,start,teacher,room,classId]);
}
if (['delete_timetable','archive_timetable','restore_timetable'].includes(action)) {
  const id=Number(p.id);if(!Number.isInteger(id)||id<1){node.error('Invalid timetable ID',msg);return null;}
  if(action==='delete_timetable')return q('_mutation_timetable','DELETE FROM timetable WHERE id=? AND NOT EXISTS (SELECT 1 FROM attendance_sessions ses WHERE ses.timetable_id=timetable.id)',[id]);
  return q('_mutation_timetable','UPDATE timetable SET active=? WHERE id=?',[action==='restore_timetable'?1:0,id]);
}
return null;

if(msg.section==='_mutation_timetable'&&msg.payload&&Number(msg.payload.affectedRows)===0){return [{_client:msg._client,payload:{notice:'Timetable conflict: the class, teacher, or room is already booked during that time',ok:false}},{_client:msg._client,payload:{action:'load_timetable'}}];}
if (msg.section === '_mutation' || msg.section === '_mutation_rooms' || msg.section === '_mutation_timetable' || msg.section === '_mutation_teachers') {
  const reload = msg.section === '_mutation' ? 'load_students' : msg.section === '_mutation_rooms' ? 'load_rooms' : msg.section === '_mutation_teachers' ? 'load_teachers' : 'load_timetable';
  const notice = msg.section === '_mutation' ? 'Student status/record updated' : msg.section === '_mutation_rooms' ? 'Room added' : msg.section === '_mutation_teachers' ? 'Teacher status updated' : 'Timetable updated';
  return [{_client:msg._client,payload:{notice,ok:true}}, {_client:msg._client,payload:{action:reload}}];
}
return [{_client:msg._client,payload:{section:msg.section,rows:Array.isArray(msg.payload)?msg.payload:[]}}, null];

const text = (msg.error && msg.error.message) ? msg.error.message : 'Database operation failed';
msg.payload = {notice:text,ok:false};
return msg;

const p=msg.payload||{};
const sid=Number(p.session_id), student=Number(p.student_id), wave=Number(p.wave_number), confidence=p.confidence==null?null:Number(p.confidence);
if(!Number.isInteger(sid)||!Number.isInteger(student)||![1,2,3].includes(wave)){msg.statusCode=400;msg.payload={ok:false,error:'session_id, student_id and wave_number (1-3) are required'};return [null,msg];}
const result=['present','absent','unclear'].includes(p.result)?p.result:'present';
msg.topic='INSERT INTO wave_results (session_id,student_id,wave_number,result,confidence) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE result=VALUES(result),confidence=VALUES(confidence),detected_at=CURRENT_TIMESTAMP';
msg.payload=[sid,student,wave,result,confidence];
return [msg,null];

const sid=Number((msg.payload||{}).session_id);
if(!Number.isInteger(sid)){msg.statusCode=400;msg.payload={ok:false,error:'session_id is required'};return [null,msg];}
msg.topic="INSERT INTO attendance (session_id,student_id,automated_status,final_status) SELECT session_id,student_id,CASE WHEN COUNT(*)<3 THEN 'review' WHEN SUM(result='present')=3 THEN 'present' WHEN SUM(result='present')=2 THEN 'review' ELSE 'absent' END,CASE WHEN COUNT(*)<3 THEN NULL WHEN SUM(result='present')=3 THEN 'present' WHEN SUM(result='present')=2 THEN NULL ELSE 'absent' END FROM wave_results WHERE session_id=? GROUP BY session_id,student_id ON DUPLICATE KEY UPDATE automated_status=VALUES(automated_status),final_status=VALUES(final_status)";
msg.payload=[sid];return [msg,null];

const p=msg.payload||{}; const role=p.role; const email=String(p.email||'').trim().toLowerCase();
if(!['admin','teacher'].includes(role)||!p.name||!email||!p.mobile||String(p.password||'').length<8){msg.statusCode=400;msg.payload={error:'Complete every field; password must contain at least 8 characters'};return [null,null,msg];}
const adminCode=String(env.get('CONTINIO_ADMIN_CODE')||'');if(role==='admin'&&(!adminCode||String(p.admin_code)!==adminCode)){msg.statusCode=403;msg.payload={error:'Invalid admin registration code'};return [null,null,msg];}
msg.reg={role,name:String(p.name).trim(),teacher_code:String(p.teacher_id||'').trim(),email,mobile:String(p.mobile).trim(),password:String(p.password)};
if(role==='teacher'){if(!msg.reg.teacher_code){msg.statusCode=400;msg.payload={error:'Teacher ID is required'};return [null,null,msg];}msg.topic="INSERT INTO teachers (name,teacher_id,email,mobile,password_hash) VALUES (?,?,?,?,?)";msg.payload=[msg.reg.name,msg.reg.teacher_code,email,msg.reg.mobile,'managed_by_continio_accounts'];return [msg,null,null];}
return [null,msg,null];

if(msg.reg.role==='teacher')msg.reg.dbTeacherId=Number(msg.payload.insertId);else msg.reg.dbTeacherId=null;
msg.topic="INSERT INTO continio_accounts (role,teacher_id,name,email,mobile,password_salt,password_hash) SELECT ?,?,?,?,?,salt,SHA2(CONCAT(?,salt),256) FROM (SELECT HEX(RANDOM_BYTES(16)) AS salt) x";
msg.payload=[msg.reg.role,msg.reg.dbTeacherId,msg.reg.name,msg.reg.email,msg.reg.mobile,msg.reg.password];return msg;

const rows=Array.isArray(msg.payload)?msg.payload:[];
if(!rows.length){msg.payload={ok:true,meta:{},schedules:[],students:[]};return msg;}
const schedules=[];const seen=new Set();
for(const r of rows){if(!seen.has(r.timetable_id)){seen.add(r.timetable_id);schedules.push({timetable_id:r.timetable_id,day:r.day_of_week,period_label:'Period '+r.period_number,time:(r.scheduled_start||'—')+'–'+(r.scheduled_end||'—'),subject:r.subject,section:r.section,room:r.room_number,session_id:r.session_id||null});}}
const requested=Number(msg.requestedTimetableId)||0;const chosen=rows.find(r=>r.timetable_id===requested)||rows[0];const selected=rows.filter(r=>r.timetable_id===chosen.timetable_id&&String(r.session_id||'')===String(chosen.session_id||''));
msg.payload={ok:true,meta:{timetable_id:chosen.timetable_id,session_id:chosen.session_id||null,day:chosen.day_of_week,period_label:'Period '+chosen.period_number,time:(chosen.scheduled_start||'—')+'–'+(chosen.scheduled_end||'—'),subject:chosen.subject,section:chosen.section,room:chosen.room_number,session_status:chosen.session_status||'scheduled',wave_progress:Math.max(0,...selected.map(r=>Number(r.waves_completed)||0))},schedules,students:selected.map(r=>({id:r.id,name:r.name,usn:r.usn,photo_url:r.photo_url,status:r.status||'present',checked_in:Number(r.checked_in)===1,waves_completed:Number(r.waves_completed)||0,review:r.automated_status==='review'}))};return msg;
